40	void quantize_row_q1_0_ref(const float * GGML_RESTRICT x, block_q1_0 * GGML_RESTRICT y, int64_t k) {
41	    static const int qk = QK1_0;
42	
43	    assert(k % qk == 0);
44	
45	    const int nb = k / qk;
46	
47	    for (int i = 0; i < nb; i++) {
48	        float sum_abs = 0.0f;
49	        for (int j = 0; j < qk; j++) {
50	            sum_abs += fabsf(x[i*qk + j]);
51	        }
52	        const float d = sum_abs / qk;
53	
54	        y[i].d = GGML_FP32_TO_FP16(d);
55	
56	        // Clear all bits first
57	        for (int j = 0; j < qk / 8; ++j) {
58	            y[i].qs[j] = 0;
59	        }
60	
61	        // Just store sign of each weight directly (no normalization)
62	        for (int j = 0; j < qk; ++j) {
63	            const int bit_index = j;
64	            const int byte_index = bit_index / 8;
65	            const int bit_offset = bit_index % 8;
66	
67	            if (x[i*qk + j] >= 0.0f) {
